package com.aadil.ecommerce.services;import com.aadil.ecommerce.dtos.InvitationDTO;import com.aadil.ecommerce.entities.AdminInvitationEntity;import com.aadil.ecommerce.exceptions.UserAlreadyExistsException;import com.aadil.ecommerce.repositories.UserRepository;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.security.NoSuchAlgorithmException;import java.security.SecureRandom;import java.time.LocalDateTime;import java.util.Base64;import java.util.HexFormat;@Service@RequiredArgsConstructorpublic class AdminService {    private final UserRepository userRepository;    private String generateInvitation (){        SecureRandom secureRandom = new SecureRandom();        byte[] randomBytes = new byte[32];        secureRandom.nextBytes(randomBytes);        return Base64.getUrlEncoder().withoutPadding().encodeToString(randomBytes);    }    public String adminInvitation (InvitationDTO dto) throws NoSuchAlgorithmException {        String name = dto.getName();        String email = dto.getEmail().trim().toLowerCase();        if (userRepository.findByEmail(email).isPresent()){            throw new UserAlreadyExistsException("This is user is already present in DB: "+email);        }        String rawToken = generateInvitation();        MessageDigest messageDigest = MessageDigest.getInstance("SHA-256");        byte[] tokeHash = messageDigest.digest(rawToken.getBytes(StandardCharsets.UTF_8));        String token = HexFormat.of().formatHex(tokeHash);        AdminInvitationEntity invitation = new AdminInvitationEntity();        invitation.setName(name);        invitation.setEmail(email);        invitation.setTokenHash(token);        invitation.setExpiresAt(LocalDateTime.now().plusHours(24));        invitation.setUsed(false);        return rawToken;    }}